.ds{--p-bg:#ffffff;--p-surface:#f1f3f6;--p-high:#fafbfc;--p-hover:#e1e6ed;--p-row-active:#e5e9f2;--p-disabled:#dce1e8;--p-glass:#f6f8fbe8;--p-backdrop:#2c333d66;--p-tile:#f2f3f0;--p-tile-header:#f3f4f1;--p-image-well:#e7e9e4;--p-selected-surface:#e7f0eb;--p-ink:#2c333d;--p-muted:#59636f;--p-on-accent:#ffffff;--p-line:#c2cad5;--p-line-subtle:#cbd2dc;--p-control-border:#7b8592;--p-edge:#ffffff;--p-edge-soft:#ffffffa8;--p-accent:#303b48;--p-accent-hover:#25303d;--p-shade:#000;--p-highlight:#6153b5;--p-highlight-soft:#e2ddf3;--p-soft:#d3e8de;--p-mark:#ffbf63;--p-mark-hover:#ffd07b;--p-mark-alt:#9ad9aa;--p-error:#a3313e;--p-error-soft:#f9e8e9;--p-error-line:#d4a2a8;--p-success:#26614f;--p-success-soft:#e5f2eb;--p-success-line:#8fb8a5;--p-warning:#805719;--p-warning-soft:#f6efd9;--p-warning-line:#b9a16f;--p-accent-shaded:color-mix(in srgb, var(--p-accent) 84%, var(--p-shade));--p-glass-veil:color-mix(in oklab, var(--p-glass) 68%, transparent);--p-high-veil:color-mix(in oklab, var(--p-high) 80%, transparent);--p-current-tint:color-mix(in oklab, currentColor 14%, transparent);--p-on-accent-muted:color-mix(in oklab, var(--p-on-accent) 74%, transparent);--p-accent-wash:color-mix(in oklab, var(--p-accent) 26%, transparent);--p-success-wash:color-mix(in oklab, var(--p-success) 34%, transparent);--p-soft-success:color-mix(in oklab, var(--p-success) 16%, var(--p-soft));--p-font:Pretendard, sans-serif;--p-mono-font:ui-monospace, SFMono-Regular, Consolas, monospace;--p-display-font:Outfit, Pretendard, sans-serif;--p-type-body:var(--p-text-md)/var(--p-leading-normal) var(--p-font);--p-type-display:var(--p-weight-semibold) var(--p-text-display) var(--p-display-font);--p-type-figure:var(--p-weight-bold) var(--p-text-md)/var(--p-leading-none) var(--p-display-font);--p-type-stat:var(--p-weight-bold) var(--p-text-lg)/var(--p-leading-tight) var(--p-display-font);--p-text-sm:12px;--p-text-body:14px;--p-text-md:16px;--p-text-title-sm:18px;--p-text-title:20px;--p-text-lg:24px;--p-text-heading:30px;--p-text-display:40px;--p-weight-light:300;--p-weight-regular:400;--p-weight-medium:500;--p-weight-semibold:600;--p-weight-bold:700;--p-weight-extrabold:800;--p-leading-none:1;--p-leading-tight:1.2;--p-leading-snug:1.35;--p-leading-normal:1.5;--p-leading-relaxed:1.65;--p-leading-loose:1.8;--p-space-unit:4px;--p-space-3xs:2px;--p-space-2xs:4px;--p-space-xs:8px;--p-space-sm:12px;--p-space-md:16px;--p-space-lg:24px;--p-space-xl:32px;--p-space-2xl:40px;--p-space-3xl:48px;--p-space-4xl:64px;--p-space-5xl:80px;--p-size-hairline:1px;--p-size-2xs:4px;--p-size-xs:8px;--p-size-sm:12px;--p-size-md:16px;--p-size-lg:24px;--p-size-xl:32px;--p-size-2xl:40px;--p-size-3xl:48px;--p-icon-xs:12px;--p-icon-sm:16px;--p-icon-md:20px;--p-icon-lg:24px;--p-icon-xl:28px;--p-icon-2xl:32px;--p-icon-3xl:40px;--p-control-size-sm:44px;--p-control-size-md:48px;--p-control-size-lg:56px;--p-control-size-xl:64px;--p-radius-xs:2px;--p-radius-sm:4px;--p-radius-md:8px;--p-radius-lg:12px;--p-radius-xl:16px;--p-radius-2xl:24px;--p-radius-full:999px;--p-radius-circle:50%;--p-inner-radius:var(--p-radius-lg);--p-control-radius:var(--p-radius-xl);--p-radius:var(--p-radius-2xl);--p-underline-offset:3px;--p-border-width:1px;--p-border-width-strong:2px;--p-border-width-focus:3px;--p-focus-offset:3px;--p-focus-offset-tight:2px;--p-shadow:6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed;--p-raised:3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed;--p-inset:inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9;--p-pressed:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18;--p-float:0 12px 32px #26394d26;--p-lift:0 3px 5px #24314526;--p-control-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24;--p-selected-shadow:0 2px 5px #24314526;--p-knob-shadow:0 1px 3px #26344726;--p-glass-shadow:0 8px 24px #38465e12;--p-dialog-shadow:0 24px 80px #26344740;--p-drop:0 10px 12px #24293616;--p-ring:inset 0 0 0 2px #24293610;--p-focus-glow:0 0 0 2px #ed667b33;--p-stage-shadow:0 24px 44px -28px #303b4873;--p-blur-sm:blur(3px);--p-blur-md:blur(16px);--p-blur-glass:blur(20px) saturate(1.2);}
.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds :is(code,pre) { font-family:var(--p-mono-font); }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-lg); height:var(--p-icon-lg); object-fit:contain; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(0)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }
.ds .ds-admin-error { color:var(--p-error); font-size:var(--p-text-body); }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:var(--p-space-2xs) var(--p-space-xs); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-full); background:var(--p-soft); color:var(--p-ink); font-size:var(--p-text-sm); line-height:var(--p-leading-normal); font-weight:var(--p-weight-semibold); }
.ds .ds-badge[data-tone="success"] { background:var(--p-success-soft); border-color:var(--p-success-line); color:var(--p-success); }
.ds .ds-badge[data-tone="error"] { background:var(--p-error-soft); border-color:var(--p-error-line); color:var(--p-error); }
.ds .ds-badge[data-tone="warning"] { background:var(--p-warning-soft); border-color:var(--p-warning-line); color:var(--p-warning); }
/* looks: tone keeps the color, look changes the surface */
.ds .ds-badge[data-look="icon"] { gap:var(--p-space-2xs); padding-left:var(--p-space-xs); }
.ds .ds-badge[data-look="icon"] .ui-icon { width:var(--p-icon-sm); height:var(--p-icon-sm); }

/* One markup, five shapes. Selection never rests on color alone: each shape adds a mark, a tile, a pill, a press or weight. */
/* Floating shapes declare --ds-bottom-nav-offset so a screen frame can keep them off the edges. */
.ds .ds-bottom-nav { position:relative; isolation:isolate; display:flex; justify-content:space-around; align-items:center; gap:var(--p-space-2xs); padding:var(--p-space-xs); background:var(--p-surface); border-top:var(--p-border-width) solid var(--p-line); }
.ds .ds-bottom-nav > :not(.ds-bottom-nav-create) { position:relative; display:flex; flex:1; min-width:var(--p-control-size-sm); min-height:var(--p-control-size-xl); flex-direction:column; justify-content:center; align-items:center; gap:var(--p-space-2xs); padding:var(--p-space-xs); border:0; color:var(--p-muted); background:transparent; font-size:var(--p-text-sm); text-decoration:none; }
.ds .ds-bottom-nav > :is([aria-pressed="true"],[aria-current="page"]) { color:var(--p-ink); font-weight:var(--p-weight-extrabold); }
.ds .ds-bottom-nav > :not(.ds-bottom-nav-create)::before,.ds .ds-bottom-nav > :not(.ds-bottom-nav-create)::after { content:''; position:absolute; pointer-events:none; }
.ds .ds-bottom-nav > .ds-bottom-nav-create { display:grid; place-items:center; flex:none; width:var(--p-control-size-md); height:var(--p-control-size-md); padding:0; border:0; border-radius:var(--p-radius-circle); color:var(--p-on-accent); background:var(--p-accent); box-shadow:var(--p-raised); }
.ds .ds-bottom-nav > .ds-bottom-nav-create .ui-icon { width:var(--p-icon-lg); height:var(--p-icon-lg); }
/* 05 line: top bar (also the look without a variant) */
.ds .ds-bottom-nav:is(:not([data-variant]),[data-variant="line"]) > :is([aria-pressed="true"],[aria-current="page"])::before { top:calc(var(--p-space-xs) * -1); left:calc(100% / 6); right:calc(100% / 6); height:var(--p-size-2xs); border-radius:0 0 var(--p-radius-sm) var(--p-radius-sm); background:var(--p-accent); }
/* 01 minimal: flat, dot under the label */
.ds .ds-bottom-nav[data-variant="minimal"] { background:var(--p-bg); border-top-color:transparent; }
.ds .ds-bottom-nav[data-variant="minimal"] > :is([aria-pressed="true"],[aria-current="page"])::after { bottom:var(--p-space-3xs); width:var(--p-size-2xs); height:var(--p-size-2xs); border-radius:var(--p-radius-circle); background:var(--p-accent); }
/* 02 glass: translucent edge bar over the screen, light tile on the chosen item */
.ds .ds-bottom-nav[data-variant="glass"] { background:var(--p-high); border-top-color:var(--p-line); }
@supports(backdrop-filter:blur(0)) { .ds .ds-bottom-nav[data-variant="glass"] { background:var(--p-glass-veil); backdrop-filter:var(--p-blur-glass); } }
.ds .ds-bottom-nav[data-variant="glass"] > :not(.ds-bottom-nav-create) { border-radius:var(--p-radius-xl); }
.ds .ds-bottom-nav[data-variant="glass"] > :is([aria-pressed="true"],[aria-current="page"]) { background:var(--p-high-veil); box-shadow:inset 0 0 0 var(--p-border-width) var(--p-line); }
/* 03 float: floating capsule, create button inside, soft disc behind the chosen icon */
.ds .ds-bottom-nav[data-variant="float"] { --ds-bottom-nav-offset:var(--p-space-sm); padding:var(--p-space-xs) var(--p-space-xs); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-full); background:var(--p-high); box-shadow:var(--p-shadow); }
.ds .ds-bottom-nav[data-variant="float"] > :not(.ds-bottom-nav-create) { min-height:var(--p-control-size-lg); }
.ds .ds-bottom-nav[data-variant="float"] > :is([aria-pressed="true"],[aria-current="page"])::before { top:var(--p-space-2xs); left:50%; width:calc(var(--p-space-unit) * 9); height:var(--p-size-xl); margin-left:calc((var(--p-space-md) + var(--p-space-3xs)) * -1); border-radius:var(--p-radius-xl); background:var(--p-soft); z-index:var(--p-layer-below); }
/* 04 pill: only the chosen item shows its name, inside a soft pill */
.ds .ds-bottom-nav[data-variant="pill"] { padding:var(--p-space-xs) var(--p-space-xs); background:var(--p-bg); }
.ds .ds-bottom-nav[data-variant="pill"] > :not(.ds-bottom-nav-create) { min-height:var(--p-control-size-sm); flex-direction:row; gap:var(--p-space-xs); border-radius:var(--p-radius-full); }
.ds .ds-bottom-nav[data-variant="pill"] > :not([aria-pressed="true"],[aria-current="page"]) > span { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.ds .ds-bottom-nav[data-variant="pill"] > :is([aria-pressed="true"],[aria-current="page"]) { flex:1.8; padding:var(--p-space-xs) var(--p-space-md); background:var(--p-soft); font-size:var(--p-text-sm); }
@media(prefers-reduced-transparency:reduce) { .ds .ds-bottom-nav[data-variant="glass"] { background:var(--p-high); backdrop-filter:none; } }

.ds .ds-page-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:var(--p-space-xs); margin:0 0 var(--p-space-lg); padding:0; list-style:none; }
.ds .ds-page-stats li { display:grid; gap:var(--p-space-3xs); padding:var(--p-space-sm); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-xl); background:var(--p-surface); }
.ds .ds-page-stats strong { font:var(--p-type-stat); letter-spacing:var(--p-tracking-tight); }
.ds .ds-page-stats span { font-size:var(--p-text-sm); color:var(--p-muted); }

.ds .ds-page { max-width:var(--p-container-xl); margin-inline:auto; }
.ds .ds-page-header { display:flex; justify-content:space-between; align-items:center; gap:var(--p-space-md); margin-bottom:var(--p-space-xl); }
.ds .ds-page-header h2 { font-size:var(--p-text-heading); font-weight:var(--p-weight-semibold); letter-spacing:var(--p-tracking-tighter); margin-top:var(--p-space-xs); }
.ds .ds-eyebrow { font-size:var(--p-text-sm); color:var(--p-muted); }
.ds .ds-page > .ds-bottom-nav { margin:var(--p-space-xl) auto 0; max-width:var(--p-container-md); }
/* Looks: how the screen opens. Each look also brings its own bottom bar shape from the markup. */
.ds .ds-page[data-look="hero"] .ds-page-header { align-items:flex-end; padding:calc(var(--p-space-unit) * 7) calc(var(--p-space-unit) * 5) calc(var(--p-space-unit) * 5); border-radius:var(--p-radius); background:var(--p-soft); }
.ds .ds-page[data-look="hero"] .ds-page-header h2 { font-size:var(--p-text-display); line-height:var(--p-leading-tight); }
.ds .ds-page[data-look="appbar"] .ds-page-header { position:relative; justify-content:center; padding:var(--p-space-2xs) var(--p-space-4xl) var(--p-space-md); margin-bottom:var(--p-space-lg); border-bottom:var(--p-border-width) solid var(--p-line); text-align:center; }
.ds .ds-page[data-look="appbar"] .ds-page-header h2 { margin-top:0; font-size:var(--p-text-title); letter-spacing:var(--p-tracking-tight); }
.ds .ds-page[data-look="appbar"] .ds-page-header > .ds-badge { position:absolute; right:0; top:50%; translate:0 calc(100% * 3 / 5 * -1); }
.ds .ds-page[data-look="sheet"] .ds-page-header { align-items:flex-start; margin-bottom:0; padding:var(--p-space-lg) calc(var(--p-space-unit) * 5) var(--p-space-4xl); border-radius:var(--p-radius) var(--p-radius) 0 0; background:var(--p-accent); color:var(--p-on-accent); }
.ds .ds-page[data-look="sheet"] .ds-page-header .ds-eyebrow { color:var(--p-on-accent-muted); }
.ds .ds-page[data-look="sheet"] .ds-page-header + * { position:relative; margin-top:calc(var(--p-space-xl) * -1); padding:var(--p-space-lg) calc(var(--p-space-unit) * 5); border-radius:var(--p-radius-2xl) var(--p-radius-2xl) 0 0; background:var(--p-high); }
.ds .ds-page[data-look="dashboard"] .ds-page-header { margin-bottom:var(--p-space-md); }
.ds .ds-template-slot { min-height:calc(var(--p-space-unit) * 40); display:grid; place-items:center; padding:var(--p-space-lg); border:var(--p-border-width) var(--p-stroke-dashed) var(--p-control-border); border-radius:var(--p-radius); color:var(--p-muted); font-size:var(--p-text-body); }

(function mountParts(root) {
  window.Pattove?.admin?.mount(root);
  root.querySelectorAll('[data-await-script]').forEach(fieldset=>{fieldset.disabled=false;fieldset.removeAttribute('data-await-script');});
  root.querySelectorAll('[data-indeterminate]').forEach(input => {
    if (!input.__pattoveInitialized) { input.indeterminate = true; input.__pattoveInitialized = true; }
  });
  const syncStepper=input=>{
    const box=input.closest('.ds-stepper');if(!box)return;
    for(const button of box.querySelectorAll('[data-step]'))button.disabled=input.disabled||(input.value!==''&&(Number(button.dataset.step)<0?input.min!==''&&input.valueAsNumber<=Number(input.min):input.max!==''&&input.valueAsNumber>=Number(input.max)));
  };
  root.querySelectorAll('.ds-stepper input').forEach(syncStepper);
  if (root.__pattovePartsMounted) return;
  root.__pattovePartsMounted = true;
  const emit = (node, name, detail) => node.dispatchEvent(new CustomEvent('pattove:' + name, {bubbles:true, detail}));
  const fieldError=(control,label)=>{
    const v=control.validity;
    const message=v.valueMissing?(control.type==='checkbox'?'체크해 주세요.':control.tagName==='SELECT'?'항목을 선택하세요.':'값을 입력하세요.'):
      v.typeMismatch?(control.type==='email'?'이메일 주소를 확인하세요.':'주소 형식을 확인하세요.'):
      v.rangeUnderflow?control.min+' 이상 입력하세요.':v.rangeOverflow?control.max+' 이하로 입력하세요.':
      v.stepMismatch?(control.step||'1')+' 간격으로 입력하세요.':v.tooLong?control.maxLength+'자 이내로 입력하세요.':
      v.customError?control.validationMessage:'입력 형식을 확인하세요.';
    return label+': '+message;
  };
  root.addEventListener('input',event=>{if(event.target.matches('.ds-stepper input'))syncStepper(event.target);});
  const formErrors = (form, errors) => {
    const summary=form.querySelector('.ds-error-summary');if(!summary)return;
    for(const control of form.querySelectorAll('[data-field-label]')){
      const error=errors.find(e=>e.id===control.id),help=document.getElementById(control.id+'-help');
      control.setAttribute('aria-invalid',String(!!error));
      if(help)help.textContent=error?.message||help.dataset.fieldHelp||'';
    }
    const list=summary.querySelector('ul');list.replaceChildren();summary.hidden=!errors.length;
    for(const error of errors){const li=document.createElement('li'),a=document.createElement('a');a.href='#'+encodeURIComponent(error.id);a.dataset.errorTarget=error.id;a.textContent=error.message;li.append(a);list.append(li);}
    if(errors.length)summary.focus();
  };
  root.addEventListener('click',event=>{const link=event.target.closest('[data-error-target]');if(!link)return;const input=document.getElementById(link.dataset.errorTarget);if(input){event.preventDefault();input.focus();input.scrollIntoView({block:'center'});}});
  // A host claims async work with event.detail.respondWith(promise). No response is never success.
  root.addEventListener('submit',async event=>{
    const form=event.target;
    if(form.matches('[data-calculator]')) {
      event.preventDefault();if(!form.reportValidity())return;
      const data=new FormData(form),result=Number(data.get('price'))*Number(data.get('quantity'));
      form.querySelector('output').textContent=Number.isFinite(result)?new Intl.NumberFormat('ko-KR',{style:'currency',currency:'KRW',maximumFractionDigits:2}).format(result):'금액을 확인하세요.';return;
    }
    if(!form.matches('[data-async-form]'))return;
    event.preventDefault();if(form.dataset.pending)return;
    if(form.matches('.ds-data-form')){
      const invalid=[...form.querySelectorAll('[data-field-label]')].filter(n=>!n.validity.valid).map(n=>({id:n.id,message:fieldError(n,n.dataset.fieldLabel)}));
      formErrors(form,invalid);form.querySelector('[role="status"]').textContent='';if(invalid.length)return;
    }else if(!form.reportValidity())return;
    const data=Object.fromEntries(new FormData(form)),status=form.querySelector('[role="status"]'),field=form.querySelector('fieldset'),controller=new AbortController();
    if(form.matches('.ds-data-form'))for(const checkbox of form.querySelectorAll('input[type="checkbox"][name]'))data[checkbox.name]=checkbox.checked;
    // Claim the form before invoking host handlers, including synchronous resubmission.
    form.dataset.pending='true';
    let promise,claimed=false,accepting=true;
    const detail={kind:form.dataset.asyncForm,values:data,signal:controller.signal,respondWith(value){if(!accepting)throw Error('respondWith must be called during the submit event');if(claimed)throw Error('Submission already handled');claimed=true;promise=Promise.resolve(value);},abort:()=>controller.abort()};
    emit(form,'submit',detail);
    accepting=false;
    if(!claimed){delete form.dataset.pending;status.textContent='요청을 처리할 수 없어요. 잠시 후 다시 시도하세요.';return;}
    form.dataset.pending='true';field.disabled=true;form.setAttribute('aria-busy','true');status.textContent='처리하고 있어요.';
    try {
      await new Promise((resolve,reject)=>{
        const abort=()=>reject(new DOMException('Request aborted','AbortError'));
        promise.then(value=>{controller.signal.removeEventListener('abort',abort);resolve(value);},error=>{controller.signal.removeEventListener('abort',abort);reject(error);});
        if(controller.signal.aborted)abort();else controller.signal.addEventListener('abort',abort,{once:true});
      });
      if(!controller.signal.aborted&&form.isConnected)status.textContent=form.dataset.successMessage||(form.dataset.asyncForm==='login'?'로그인했어요.':'저장했어요.');
    }
    catch(error) {if(form.isConnected&&!controller.signal.aborted){
